export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds,
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholds && Object.keys(thresholds).length > 0) {
    const thresholdsList = [];
    let allPassed = true;

    for (const [metricId, min] of Object.entries(thresholds)) {
      const metric = evaluations.find((m) => m.id === metricId);
      const score = metric?.score;
      const passed = score !== null && score !== undefined && score >= min;
      if (!passed) allPassed = false;

      thresholdsList.push({
        metric: metricId,
        min,
        score: score ?? null,
        passed
      });
    }

    report.passed = allPassed;
    report.thresholds = thresholdsList;
  }

  return report;
}

